<?php
// Dar — read-only (nothing changed or sent): why a new sign-up was asked to pay at once (its plan's free days, its trial check), and
// what the site's visitor assistant knows and how it answered lately
$R = '/home/u791571885/domains/dar.ink/public_html'; require $R . '/dar-sync.php';
$o = ['v' => SYNC_VERSION, 'now' => gmdate('c'), 'checkout_first' => function_exists('trial_checkout_first_on') ? trial_checkout_first_on() : null, 'card_ready' => function_exists('trial_card_ready') ? trial_card_ready() : null, 'renew' => bill_cfg()['renew'] ?? null];
$o['plans'] = array_map(fn($p) => array_intersect_key(o2a($p) ?: [], array_flip(['code', 'audience', 'base_price', 'trial_days', 'trial_days_month', 'trial_days_year', 'active', 'discount_pct'])), bill_platform_rows('plans'));
$o['new'] = array_map(function ($r) { $T = tenant_obj($r); $tr = is_object($T->trial ?? null) ? o2a($T->trial) : null; return ['id' => $r['id'], 'app' => $r['app'], 'status' => $r['status'], 'reason' => (string)($T->suspend_reason ?? ''), 'checkout_first' => !empty($T->checkout_first), 'plan' => (string)($T->plan ?? ''), 'aud' => (string)($T->audience ?? ''), 'cycle' => (string)($T->signup_cycle ?? ''), 'trial_end' => (string)($T->trial_end ?? ''), 'trial' => $tr, 'created' => (string)($T->created ?? ''), 'country' => (string)($T->country ?? ''), 'mor' => is_object($T->mor ?? null) ? array_intersect_key(o2a($T->mor), array_flip(['p', 'status', 'cycle'])) : null]; }, q("SELECT * FROM tenants ORDER BY created DESC LIMIT 6")->fetchAll());
try { $o['ledger'] = array_map(fn($r) => array_intersect_key($r, array_flip(['at', 'tenant', 'code', 'app', 'result', 'why'])), q('SELECT * FROM trial_ledger ORDER BY at DESC LIMIT 8')->fetchAll()); } catch (Throwable $e) { $o['ledger'] = 'none'; }
$o['txns'] = array_map(function ($r) { $d = json_decode((string)$r['data'], true) ?: []; return ['ns' => $r['ns'], 'kind' => $r['kind'], 'status' => $r['status'], 'at' => gmdate('c', (int)($r['at'] / 1000)), 'trial' => $d['trial'] ?? null, 'first' => $d['first'] ?? ($d['amount'] ?? null), 'plan' => $d['plan'] ?? null, 'coupon' => $d['coupon'] ?? null]; }, q('SELECT * FROM pay_txns ORDER BY at DESC LIMIT 6')->fetchAll());
$o['ai_demo'] = q("SELECT provider, COUNT(*) n, SUM(ok) ok, CAST(AVG(ms) AS INTEGER) ms, MAX(ms) mx FROM ai_log WHERE at > ? AND ns IN ('', 'site', 'public', 'demo') GROUP BY provider", [now_ms() - 6 * 3600000])->fetchAll();
$o['ai_ns'] = q("SELECT ns, COUNT(*) n FROM ai_log WHERE at > ? GROUP BY ns ORDER BY n DESC LIMIT 6", [now_ms() - 6 * 3600000])->fetchAll();
$o['coupons'] = count(array_filter(bill_platform_rows('coupons'), fn($c) => ($c->active ?? true) !== false));
echo json_encode($o, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), "\n";
